<script setup lang="ts">
import {computed,ref,watch,onBeforeUnmount,onMounted} from 'vue';
import {experienceRequest as request,type Row,type Step} from '../experienceApi';
import {type PlanScope,type PlanContext,type TeachingPlan,type Proposal,proposalCurrent,appendProposal,constraintError,teachingSaveInput,rebaseProposal} from '../teachingPlan';
import {planDraftKey,planHasEdits,cacheUnsavedPlan,readUnsavedPlan,clearUnsavedPlan} from '../planDraftCache';
import {notifyError} from '../notification';
import {indicatorLabel,percentText} from '../experienceDisplay';
import {materialActionLabel} from '../materialPresentation';
import TeacherPlanEditor from './TeacherPlanEditor.vue';
import UiCheckbox from './UiCheckbox.vue';
const props=defineProps<{scopeType:PlanScope;studentId:string;classId:string;nodeId:string;refresh:number;indicators:{id:string;label:string}[]}>();
const emit=defineEmits<{learning:[id:string];question:[id:string]}>();
const context=ref<PlanContext|null>(null),draft=ref<TeachingPlan|null>(null),proposal=ref<Proposal|null>(null),focus=ref<string[]>([]),adopted=ref<string[]>([]),busy=ref(''),failed=ref(false),notice=ref('');let epoch=0,requestEpoch=0,applying=false;const externalConflict=ref(false);
const clone=<T,>(v:T):T=>JSON.parse(JSON.stringify(v));
const dirty=computed(()=>!!draft.value&&!!context.value&&planHasEdits(draft.value,context.value));
const savedLocation=computed(()=>props.classId+' / '+(props.scopeType==='CLASS'?'班级共同方案':props.studentId+' 个人方案')+' / 测验 '+props.nodeId);
function protectEdits(){if(!applying&&draft.value&&context.value)cacheUnsavedPlan(draft.value,context.value,proposal.value,adopted.value,focus.value);}
watch([draft,context,proposal,adopted,focus],protectEdits,{deep:true,flush:'sync'});
function beforeUnload(event:BeforeUnloadEvent){if(dirty.value){event.preventDefault();event.returnValue='';}}
onMounted(()=>window.addEventListener('beforeunload',beforeUnload));
const summaries=computed<Row[]>(()=>context.value?.summary.indicatorSummaries||[]);
const eligible=computed(()=>summaries.value.filter(s=>s.availableQuestionCount>0));
const validProposal=computed(()=>!externalConflict.value&&!!proposal.value&&!!context.value&&proposalCurrent(proposal.value,context.value));
const remaining=computed(()=>proposal.value?.steps.filter(s=>!adopted.value.includes(s.id)&&!draft.value?.steps.some(e=>e.id===s.id))||[]);
const minutes=computed(()=>draft.value?.steps.reduce((n,s)=>n+(s.durationMinutes||0),0)||0);
const validation=computed(()=>draft.value?constraintError(draft.value.constraints,focus.value.length):'');
const targetReady=computed(()=>!!props.nodeId&&!!props.classId&&(props.scopeType==='CLASS'||!!props.studentId));
function identity(){return {scopeType:props.scopeType,classId:props.classId,nodeId:props.nodeId,...(props.scopeType==='STUDENT'?{studentId:props.studentId}:{})};}
function invalidate(){requestEpoch++;proposal.value=null;adopted.value=[];}
async function load(){protectEdits();applying=true;const turn=++epoch;externalConflict.value=false;invalidate();context.value=null;draft.value=null;focus.value=[];notice.value='';failed.value=false;busy.value='';if(!targetReady.value){applying=false;return;}busy.value='正在读取完整学情与方案';try{const c=await request<PlanContext>('/teaching-plans?'+new URLSearchParams(identity()));if(turn!==epoch)return;const cached=readUnsavedPlan(planDraftKey(c.plan));if(cached){const unsaved=planHasEdits(cached.draft,cached.context);context.value=clone(unsaved?cached.context:c);draft.value=clone(unsaved?cached.draft:c.plan);proposal.value=clone(cached.proposal);adopted.value=clone(cached.adopted);notice.value=unsaved?'已恢复本次页面会话中未保存的编辑，请保存草稿。':'已读取后台保存的方案，并恢复本次页面会话中的候选预览。';externalConflict.value=cached.context.revision!==c.revision||cached.context.plan.revision!==c.plan.revision||cached.context.knowledgeVersion!==c.knowledgeVersion;if(externalConflict.value)notice.value+='服务端方案或依据已变化，旧候选不可采用，请放弃本地编辑后重新读取并生成。';focus.value=clone(cached.focus);}else{context.value=c;draft.value=clone(c.plan);focus.value=[...eligible.value].sort((a,b)=>(b.needsPracticeCount||0)-(a.needsPracticeCount||0)||(a.scorePercent??101)-(b.scorePercent??101)).slice(0,2).map(s=>s.indicatorId);}}catch(e){if(turn===epoch){failed.value=true;notifyError(e,'方案读取失败');}}finally{if(turn===epoch){busy.value='';applying=false;protectEdits();}}}
async function discard(){if(!draft.value)return;const key=planDraftKey(draft.value);draft.value=null;context.value=null;proposal.value=null;clearUnsavedPlan(key);await load();}

watch(()=>[props.scopeType,props.studentId,props.classId,props.nodeId,props.refresh],load,{immediate:true,flush:'sync'});
onBeforeUnmount(()=>{protectEdits();epoch++;requestEpoch++;window.removeEventListener('beforeunload',beforeUnload);});
function toggle(id:string,value:boolean){focus.value=value?[...focus.value,id]:focus.value.filter(v=>v!==id);invalidate();}
async function generate(){if(externalConflict.value){notifyError(new Error('方案或学情已变化，请先放弃本地编辑与候选并读取已保存方案'));return;}if(!draft.value||!context.value||busy.value)return;if(validation.value||!focus.value.length){notifyError(new Error(validation.value||'请至少选择一个本次有可用题的知识点'));return;}const turn=epoch,operation=++requestEpoch;proposal.value=null;adopted.value=[];notice.value='';busy.value='正在生成方案建议';const input={...identity(),indicatorIds:[...focus.value],constraints:clone(draft.value.constraints),expectedRevision:context.value.revision,expectedPlanRevision:context.value.plan.revision};try{const p=await request<Proposal>('/teaching-plans/generate','POST',input);if(turn===epoch&&operation===requestEpoch){if(!proposalCurrent(p,context.value!))throw new Error('生成期间学习依据已变化，请刷新后重试');proposal.value=p;}}catch(e){if(turn===epoch&&operation===requestEpoch)notifyError(e,'方案生成失败');}finally{if(turn===epoch)busy.value='';}}
async function adopt(ids:string[]){const turn=epoch;if(!draft.value||!context.value||!proposal.value||!validProposal.value||busy.value)return;const valid=ids.filter(id=>!adopted.value.includes(id));try{const pending=clone(draft.value);pending.steps=appendProposal(pending.steps,proposal.value,context.value,valid);await persist(pending,'DRAFT',valid);}catch(e){if(turn===epoch)notifyError(e,'采用并保存失败');}}
async function persist(pending:TeachingPlan,status:string,adopting:string[]=[]){if(externalConflict.value)throw new Error('方案或学情已变化，请先放弃本地编辑与候选并读取已保存方案');const before=clone(context.value!);const input=teachingSaveInput(pending,before,status);const turn=epoch;busy.value=adopting.length?'正在采用并保存草稿':'正在保存方案';try{const p=await request<TeachingPlan>('/teaching-plans','PUT',input);if(turn===epoch){const kept=rebaseProposal(proposal.value,before,p);applying=true;context.value={...before,plan:clone(p)};draft.value=clone(p);proposal.value=kept;adopted.value.push(...adopting);applying=false;protectEdits();notice.value=status==='CONFIRMED'?'方案已保存并确认，学生可查看当前任务。':adopting.length?'建议已采用并保存为草稿，返回此对象可继续编辑。':'草稿已保存，返回此对象可继续编辑。';}}finally{if(turn===epoch)busy.value='';}}
async function save(status:string){const turn=epoch;if(!draft.value||!context.value||busy.value)return;try{await persist(clone(draft.value),status);}catch(e){if(turn===epoch)notifyError(e,'方案保存失败');}}

</script>
<template>
<div class="plan-workbench" data-testid="plan-workbench" :data-scope="scopeType">
<p v-if="!targetReady" class="card muted">{{scopeType==='CLASS'?'先选择班级与测验范围，安排全班共同任务。':'先选择班级、学生与测验范围，编排个人学习方案。'}}</p>
<p v-if="busy" role="status">{{busy}}…</p><p v-if="notice" role="status">{{notice}}</p><p v-if="failed" class="card">方案暂时无法读取。<button @click="load">重新读取</button></p>
<template v-if="draft&&context">
<section class="card plan-evidence"><h2>{{scopeType==='CLASS'?'班级整体学情':'个人学情'}} · 本次测验</h2><p class="muted">以下基于目标范围全部有效记录。缺少证据不等于未掌握；班级平均表现不代表每位学生。</p><dl class="flow-summary"><div><dt>学生人数</dt><dd>{{context.summary.studentCount}}</dd></div><div><dt>有效记录</dt><dd>{{context.summary.recordCount}}</dd></div><div><dt>已评分</dt><dd>{{context.summary.scoredCount}}</dd></div><div><dt>得分率</dt><dd>{{percentText(context.summary.scorePercent)}}</dd></div></dl></section>
<section class="card plan-generator"><h2>根据学情生成{{scopeType==='CLASS'?'班级':'个人'}}方案建议</h2><p class="muted">选择知识点并限定目标、时长与步数。AI输出为建议，采用后仍需教师核对与确认。</p>
<label>教学目标<textarea v-model="draft.constraints.objective" maxlength="500" :disabled="!!busy" @input="invalidate" placeholder="例如：通过学习材料与练习巩固本次薄弱知识点"/></label>
<div class="plan-limits"><label>总时长（分钟）<input v-model.number="draft.constraints.durationMinutes" type="number" min="10" max="180" :disabled="!!busy" @input="invalidate"/></label><label>候选最多步数<input v-model.number="draft.constraints.maxSteps" type="number" min="1" max="12" :disabled="!!busy" @input="invalidate"/></label></div>
<fieldset class="plan-focus"><legend>关注知识点 · 默认优先2项，可调整</legend><div v-for="s in summaries" :key="s.indicatorId" class="focus-option"><UiCheckbox :model-value="focus.includes(s.indicatorId)" :label="indicatorLabel(s.indicatorId,indicators)" :disabled="!!busy||!s.availableQuestionCount" @update:model-value="toggle(s.indicatorId,$event)"/><small>得分率 {{percentText(s.scorePercent)}} · 需练习 {{s.needsPracticeCount}} 人 · 证据不足 {{s.insufficientCount}} 人 · 本次可用题 {{s.availableQuestionCount??'待读取'}}</small></div></fieldset>
<p v-if="validation" class="muted">{{validation}}</p><div class="assistant-action"><button class="primary" :data-testid="scopeType==='CLASS'?'generate-class-plan':'generate-student-plan'" :disabled="!!busy||!focus.length||!!validation" @click="generate">{{busy==='正在生成方案建议'?'正在生成，请稍候…':'生成方案建议'}}</button></div>
</section>
<section v-if="proposal" class="card proposal-preview" data-testid="plan-proposal"><div class="section-heading"><h2>待采用建议 · {{proposal.steps.length}} 步</h2><button :disabled="!validProposal||!remaining.length||!!busy" @click="adopt(remaining.map(s=>s.id))">全部采用并保存草稿</button></div><p v-if="!validProposal" class="muted">候选对应的计划或学情版本已变化，不能继续采用，请重新生成。</p><p>{{proposal.explanation}}</p><p v-for="c in proposal.cautions" :key="c" class="muted">{{c}}</p><article v-for="(s,i) in proposal.steps" :key="s.id" class="flow-row"><h3>{{i+1}} · {{s.title}} <small>{{s.durationMinutes}}分钟</small></h3><p>{{s.action}}</p><p class="muted">安排理由与学情依据：{{s.reason}}</p><div class="button-row"><button v-if="s.indicatorId" @click="emit('learning',s.indicatorId)">查看学习卡</button><button v-for="id in s.materialIds" :key="id" @click="emit('question',id)">{{materialActionLabel(id)}}</button><button :disabled="!!busy||!validProposal||!remaining.some(r=>r.id===s.id)" @click="adopt([s.id])">{{remaining.some(r=>r.id===s.id)?'采用并保存草稿':'已采用并保存'}}</button></div><details><summary>证据与已审核来源</summary><p>学情证据：{{s.evidenceIds.join('、')||'暂无直接证据，请补充观察'}}</p><blockquote v-for="source in proposal.sources.filter(v=>s.sourceIds?.includes(v.id))" :key="source.id">{{source.title}} · {{source.location}}<p>{{source.excerpt}}</p></blockquote></details></article><details><summary>生成信息与参考来源</summary><p>{{proposal.provider}} · {{proposal.model}} · 建议草稿</p><p v-for="s in proposal.sources" :key="s.id">{{s.title}} · {{s.location}}</p></details></section>
<section class="card plan-save-state" aria-live="polite" data-testid="plan-save-state"><strong>{{dirty?'有未保存修改':context.plan.revision>0?'当前方案已保存':'当前尚未保存方案'}}</strong><p>保存位置：{{savedLocation}}</p><p class="muted">{{dirty?'本次页面会话内切换后会保留编辑；刷新或关闭前请保存草稿。':'草稿保存在当前对象的教学方案中；教师确认后才成为学生学习任务。'}}</p><button v-if="dirty||externalConflict||(proposal&&!validProposal)" :disabled="!!busy" @click="discard">放弃本地编辑与候选，读取已保存方案</button></section>
<p class="muted">方案 {{draft.steps.length}} 步 · 已安排 {{minutes}} / {{draft.constraints.durationMinutes}} 分钟（旧步骤未标时长不计入）</p>
<TeacherPlanEditor :key="scopeType+classId+studentId+nodeId" :plan="draft" :busy="!!busy" :indicators="indicators" @save="save" @learning="emit('learning',$event)" @question="emit('question',$event)"/>
</template></div>
</template>
<style scoped>
.plan-workbench{display:grid;gap:20px}.plan-workbench>.card{margin:0}.plan-limits{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-top:12px}.plan-focus{border:1px solid var(--line);border-radius:12px;padding:16px;margin-top:20px;display:grid;gap:12px}.plan-focus legend{padding:0 8px;color:var(--muted);font-size:13px}.focus-option{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:6px 16px}.focus-option small{color:var(--muted);font-size:12px}.proposal-preview h3 small{font-weight:400;color:var(--muted)}@media(max-width:550px){.plan-limits{grid-template-columns:1fr}.focus-option{align-items:flex-start;flex-direction:column}.plan-focus{padding:12px}.proposal-preview .section-heading{align-items:flex-start;gap:12px;flex-direction:column}}
</style>
